// One batch of domains -> Supersoniq enrich request bodies. Mirrors the seniority
// doctrine of the old parent-level Build SQ Requests (2026-08); only the data source
// changed: everything arrives through Batch Input instead of $('Parse Domains').
const inp = $('Batch Input').first().json;
const domains = Array.isArray(inp.domains) ? inp.domains : [];
if (!domains.length) { throw new Error('SQ Contacts Batch received an empty domain batch. The parent must never send one.'); }
const cmap = inp.cmapSlice || {};
const countries = (Array.isArray(inp.countries) ? inp.countries : []).map(c => String(c).trim()).filter(Boolean);

// Decision-maker tier, fixed - not a form choice. 'Unclassified' is included: an
// unreliable classifier saying 'we don't know' is not the same as 'not a decision-maker'.
// Department is never sent - same reasoning, we don't trust the classification enough
// to let it silently exclude someone.
const STANDARD_SEN = ['Manager', 'Senior Manager', 'Director', 'Head', 'VP', 'EVP / SVP', 'President', 'C-Suite', 'Owner', 'Founder', 'Partner', 'Board / Chair', 'Unclassified'];
// At small companies a bare 'Senior' title is often the de facto decision-maker - company
// structure is flat enough that title doesn't mean what it means at a 500-person company.
const SMALL_SEN = STANDARD_SEN.concat(['Senior']);
const SMALL_MAX_EMPLOYEES = 10;
// Circuit-breaker, not a target - real per-company yield varies a lot, this just stops
// one outlier account from ballooning a single run's spend.
const PER_COMPANY_LIMIT = 12;

const small = [], standard = [];
for (const d of domains) {
  const emp = Number((cmap[d] || {}).Employees);
  (Number.isFinite(emp) && emp > 0 && emp <= SMALL_MAX_EMPLOYEES ? small : standard).push(d);
}

const chunk = (arr, n) => { const out = []; for (let i = 0; i < arr.length; i += n) out.push(arr.slice(i, i + n)); return out; };
const buildItems = (list, seniority) => {
  const filters = { seniority };
  if (countries.length) filters.contact_countries = countries;
  return chunk(list, 1000).map(c => ({ json: { companies: c.map(d => ({ domain: d })), filters: filters, per_company_limit: PER_COMPANY_LIMIT, tier: 'full' } }));
};

return [...buildItems(standard, STANDARD_SEN), ...buildItems(small, SMALL_SEN)];

// Supersoniq responses for one batch -> row payloads + counters, in ONE item.
// Adapted from the retired parent-level Format Supersoniq: cmap/xmap/tag/runId/buildDate
// now arrive through Batch Input, and instead of emitting 16k row items into the parent
// this returns a single { rows: [...], ...counters } item that dies with this sub-execution.
// Never throws on a failed or empty Supersoniq response: sqAllFailed rides in the summary
// and the parent's loop control decides retry vs loud fail, mirroring SL Batch Pull.
const inp = $('Batch Input').first().json;
const cmap = inp.cmapSlice || {};
const xmap = inp.xmapSlice || {};
const runId = String(inp.runId || '');
const tag = ((inp.tag || '') + '').trim();
const buildDate = String(inp.buildDate || '') || $now.toFormat('yyyy-MM-dd');

const cap = (s) => s ? s.charAt(0).toUpperCase() + s.slice(1).toLowerCase() : '';
const cleanFirst = (full) => { if (!full) return ''; const tok = String(full).split(',')[0].trim().split(/\s+/)[0] || ''; return cap(tok.replace(/[^A-Za-z'\-]/g, '')); };
const cleanLast = (full) => { if (!full) return ''; const parts = String(full).split(',')[0].trim().split(/\s+/); if (parts.length < 2) return ''; return parts.slice(1).map(p => cap(p.replace(/[^A-Za-z'\-]/g, ''))).filter(Boolean).join(' '); };
const band = (n) => { n = Number(n); if (!Number.isFinite(n) || n <= 0) return ''; if (n <= 10) return '1-10'; if (n <= 50) return '11-50'; if (n <= 200) return '51-200'; if (n <= 500) return '201-500'; if (n <= 1000) return '501-1000'; if (n <= 5000) return '1001-5000'; if (n <= 10000) return '5001-10000'; return '10001+'; };
const numOr = (v) => { if (v === null || v === undefined || String(v).trim() === '') return ''; const n = Number(v); return Number.isFinite(n) ? n : ''; };

const rows = [];
let skipped = 0, companiesMatched = 0, credits = 0, failedChunks = 0, okChunks = 0;
let firstError = '';
const withContacts = new Set();
for (const it of $('SQ Enrich').all()) {
  const resp = it.json || {};
  if (!Array.isArray(resp.results)) {
    failedChunks++;
    if (!firstError) firstError = JSON.stringify(resp).slice(0, 300);
    continue;
  }
  okChunks++;
  const results = resp.results;
  companiesMatched += results.length;
  const cr = resp.credits_used != null ? resp.credits_used : (resp.credits != null ? resp.credits : ((resp.usage && resp.usage.credits_used) || 0));
  credits += Number(cr) || 0;
  for (const r of results) {
    const contacts = Array.isArray(r.contacts) ? r.contacts : [];
    for (const ct of contacts) {
      const domain = String(ct.company_domain || '').trim().toLowerCase();
      const co = cmap[domain] || {};
      const extras = xmap[domain] || {};
      const full = ((String(ct.first_name || '') + ' ' + String(ct.last_name || '')).trim()) || String(ct.full_name || '');
      const first = cleanFirst(full); const last = cleanLast(full);
      const key = (first.toLowerCase() + last.toLowerCase() + domain).trim();
      if (!key) { skipped++; continue; }
      if (domain) withContacts.add(domain);
      // Raw here; the Clean Fields helper (downstream) writes the cleaned Company / company_clean / State Full.
      const coName = String(co.Company || ct.company_name || '').trim();
      rows.push({
        ...extras,
        'Contact Key': key,
        Name: full, first_name: first, last_name: last,
        Title: String(ct.job_title || ''), Seniority: String(ct.seniority || ''), Department: String(ct.function || ''),
        Email: String(ct.email || ''), Social: String(ct.linkedin_url || ''),
        Phone: '', Connections: '',
        Domain: domain, Company: coName, company_clean: coName,
        'Industry Groups': co['Industry Groups'] || '', Employees: band(co.Employees),
        'Business Model': co['Business Model'] || '', 'MX Provider': co['MX Provider'] || '',
        Score: '', Similarity: '', Description: co.Description || '', Keywords: '',
        City: co.City || '', State: co.State || '', 'State Full': '', Country: co.Country || '',
        Zip: '', Street: '', Source: 'Supersoniq', 'Run ID': runId, 'Build Date': buildDate, Tag: tag,
        Plan: co.Plan || '',
        'Revenue Est Monthly': numOr(co['Revenue Est Monthly']),
        'Store Age Years': numOr(co['Store Age Years']),
        'Product Count': numOr(co['Product Count']),
        'App Spend Mo': numOr(co['App Spend Mo']),
        'Key Apps': co['Key Apps'] || '', 'Tech Stack': co['Tech Stack'] || '',
        'Trustpilot Rating': numOr(co['Trustpilot Rating']),
        'Trustpilot Reviews': numOr(co['Trustpilot Reviews']),
        'Migrated From': co['Migrated From'] || '', 'Social Followers': co['Social Followers'] || '',
        'Growth 90d': numOr(co['Growth 90d']), Features: co.Features || ''
      });
    }
  }
}

return [{ json: {
  delivered: rows.length,
  skipped,
  companiesMatched,
  credits,
  failedChunks,
  sqAllFailed: okChunks === 0,
  firstError,
  withContacts: [...withContacts],
  rows
} }];

// Write-boundary standard, Operator ruling 2026-08-12. Removes everything retired from the contract
// so the payload can never resurrect a banned column or 422 on a fresh table that lacks it:
// Build Date (computed), Run ID (retired), company_clean (cleaning lives on Company itself),
// Score / Similarity / Valid / Start Date / Redirect Domain / Update Date (CSV noise, banned),
// State Full folds into State (full name wins), Source maps to Contact Source (provenance).
const BAN = ['Build Date', 'Run ID', 'company_clean', 'Score', 'Similarity', 'Valid', 'Start Date', 'Redirect Domain', 'Update Date', 'MV'];
return $input.all().map(i => { const j = { ...i.json };
  if (j['State Full'] !== undefined) { if (String(j['State Full'] || '').trim()) j['State'] = j['State Full']; delete j['State Full']; }
  if (Object.prototype.hasOwnProperty.call(j, 'Source')) { if (j['Contact Source'] === undefined) j['Contact Source'] = j.Source; delete j.Source; }
  for (const k of BAN) delete j[k];
  return { json: j }; });

// The ONLY thing that crosses back into the parent: counters, never rows.
// A helper owns no run-log row; its outcome rolls up into the caller's row.
const m = $('Format Batch').first().json;
let written = 0; try { written = $('Upsert Contacts').all().length; } catch (e) { written = 0; }
return [{ json: {
  delivered: Number(m.delivered) || 0,
  written,
  skipped: Number(m.skipped) || 0,
  companiesMatched: Number(m.companiesMatched) || 0,
  credits: Number(m.credits) || 0,
  failedChunks: Number(m.failedChunks) || 0,
  sqAllFailed: !!m.sqAllFailed,
  firstError: m.firstError || '',
  withContacts: Array.isArray(m.withContacts) ? m.withContacts : []
} }];
